class Solution(object):
    def numDecodings(self, s):
        """
        :type s: str
        :rtype: int
        """
        if len(s) == 0:
            return 0
        ans = [0 for _ in range(len(s) + 1)]
        ans[len(s)] = 1
        if s[len(s) - 1] != "0":
            ans[len(s) - 1] = 1
        for i in range(len(s) - 2, -1, -1):
            if s[i] != '0':
                if int(s[i:i + 2]) <= 26:
                    ans[i] = ans[i + 1] + ans[i + 2]
                else:
                    ans[i] = ans[i + 1]
        return ans[0]
